  helper_ref                          TEXT                ,                     -- FK to a TypeHelper, when this attribute is an inline-nested object auto-promoted to a helper.
  raw_json                            TEXT                                      -- Escape hatch: unmodeled JSON-Schema specifics, including oneOf bodies (v1 parking lot for n=1 cases).
);
