-- ----------------------------------------------------------------------------
-- TypeUpgradeOps: Atomic operations within a TypeUpgrade. Most upgrades decompose into 1-4 ops. OpKind controls semantics (vocabulary: AddOptional, AddWithDefault, Remove, RequireToOptional, OptionalToRequire, EnumVersionBump, CoerceToEnum, UpgradeChild, UpgradeChildIf, UpgradeListItems, UpgradeListItemsIf, AddProjected, Custom).
-- ----------------------------------------------------------------------------
CREATE TABLE type_upgrade_ops (
  type_upgrade_ops_id                 TEXT                 PRIMARY KEY,         -- Primary key (auto-synthesized: TypeUpgradeOps had no field named 'Id' or ending in 'Id').
  type_upgrade                        TEXT                ,                     -- Foreign key to the parent TypeUpgrade.
  idx                                 INTEGER             ,                     -- Execution order within the upgrade.
  op_kind                             TEXT                ,                     -- Op vocabulary: AddOptional, AddWithDefault, Remove, RequireToOptional, OptionalToRequire, EnumVersionBump, CoerceToEnum, UpgradeChild, UpgradeChildIf, UpgradeListItems, UpgradeListItemsIf, AddProjected, Custom.
  field_name                          TEXT                ,                     -- The attribute name being touched (most ops).
  literal_value                       TEXT                ,                     -- JSON-encoded literal default (AddWithDefault) or source field name (AddProjected).
  from_version                        TEXT                ,                     -- Source version for conditional upgrades (UpgradeChildIf, UpgradeListItemsIf).
  to_version                          TEXT                ,                     -- Target version for explicit version bumps.
  enum_version_ref                    TEXT                ,                     -- FK for enum-related ops (EnumVersionBump, CoerceToEnum).
  projection_ref                      TEXT                ,                     -- FK for AddProjected ops.
  raw_script                          TEXT                ,                     -- Per-op Python escape hatch for Custom ops. Snippet runs in scope of `self` and `data` dict.
  description                         TEXT                                      -- Optional op-level description.
);
