COMMENT ON COLUMN type_upgrade_ops.idx IS 'Execution order within the upgrade.';
COMMENT ON COLUMN type_upgrade_ops.op_kind IS 'Op vocabulary: AddOptional, AddWithDefault, Remove, RequireToOptional, OptionalToRequire, EnumVersionBump, CoerceToEnum, UpgradeChild, UpgradeChildIf, UpgradeListItems, UpgradeListItemsIf, AddProjected, Custom.';
COMMENT ON COLUMN type_upgrade_ops.field_name IS 'The attribute name being touched (most ops).';
COMMENT ON COLUMN type_upgrade_ops.literal_value IS 'JSON-encoded literal default (AddWithDefault) or source field name (AddProjected).';
COMMENT ON COLUMN type_upgrade_ops.from_version IS 'Source version for conditional upgrades (UpgradeChildIf, UpgradeListItemsIf).';
COMMENT ON COLUMN type_upgrade_ops.to_version IS 'Target version for explicit version bumps.';
COMMENT ON COLUMN type_upgrade_ops.enum_version_ref IS 'FK for enum-related ops (EnumVersionBump, CoerceToEnum).';
